const $=s=>document.querySelector(s);const targets={sars:['Main protease (Mpro)','SARS-CoV-2 · Mpro'],flu:['Neuraminidase','Influenza A · Neuraminidase'],hcv:['NS3/4A protease','Hepatitis C · NS3/4A'],custom:['Custom protein target','Custom research context']};
const base=Array.from({length:12},(_,i)=>({id:`FZ-${String(i+1).padStart(3,'0')}`,scaffold:['Scaffold A','Scaffold B','Scaffold C','Scaffold D'][i%4],score:[87,82,79,75,71,68,64,59,55,48,41,34][i],unc:[18,27,41,22,55,36,67,48,72,61,83,77][i]}));let data=base.map(x=>({...x})),view='overview',runCount=1,busy=false;let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('fairouz-shortlist')||'[]').filter(x=>base.some(c=>c.id===x)))}catch{}let activeContext='SARS-CoV-2 · Mpro';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}function priority(c){return c.score>=75&&c.unc<45?'Review first':'Explore'}function visible(){const q=$('#search').value.toLowerCase(),f=$('#filter').value;return data.filter(c=>(c.id+' '+c.scaffold).toLowerCase().includes(q)).filter(c=>(view!=='shortlist'||saved.has(c.id))&&(f!=='review'||priority(c)==='Review first')&&(f!=='saved'||saved.has(c.id)))}
function render(){const rows=visible();$('#compoundRows').innerHTML=rows.length?rows.map(c=>`<tr><td><button class="compound-link" data-detail="${c.id}"><span class="molecule">⬡</span><span><strong>${c.id}</strong><small>${c.scaffold} · fictional</small></span></button></td><td><div class="score">${c.score}<span class="bar"><i style="width:${c.score}%"></i></span></div></td><td><span class="uncertainty">${c.unc} / 100</span></td><td><span class="priority ${priority(c)==='Explore'?'explore':''}">${priority(c)}</span></td><td><button class="save ${saved.has(c.id)?'saved':''}" data-save="${c.id}" aria-label="${saved.has(c.id)?'Remove':'Save'} ${c.id}" aria-pressed="${saved.has(c.id)}">${saved.has(c.id)?'★':'☆'}</button></td></tr>`).join(''):'<tr><td colspan="5">No matching candidates. Try another filter or save a candidate to your shortlist.</td></tr>';$('#resultCount').textContent=rows.length;$('#savedCount').textContent=saved.size;$('#statSaved').textContent=saved.size;$('#tableSummary').textContent=`${rows.length} fictional compounds · no efficacy claims`;$('#dots').innerHTML=data.map(c=>`<button class="dot ${c.unc>50?'pale':''}" style="left:${c.unc}%;bottom:${c.score}%" title="${c.id}: demo score ${c.score}, uncertainty ${c.unc}" aria-label="Inspect ${c.id}, demo score ${c.score}, uncertainty ${c.unc}" data-detail="${c.id}"></button>`).join('')}
function setView(v){view=v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#crumb').textContent={overview:'Overview',screen:'New screening',library:'Compound library',shortlist:'Shortlist',method:'Method & evidence'}[v];$('#methodSection').hidden=v!=='method';$('#overview').hidden=v==='method';$('.stats').hidden=['screen','library','shortlist'].includes(v);$('.main-grid').hidden=['library','shortlist'].includes(v);$('.results-grid').hidden=v==='screen';$('#resultsTitle').textContent=v==='shortlist'?'Your research shortlist':v==='library'?'Compound library':'Prioritised candidates';render();if(v==='screen')$('#screenPanel').scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#newRun').onclick=()=>setView('screen');$('#viewAll').onclick=()=>setView('library');$('#methodLink').onclick=e=>{e.preventDefault();setView('method')};$('#search').oninput=render;$('#filter').onchange=render;
$('#virus').onchange=()=>{const k=$('#virus').value;$('#targetName').textContent=targets[k][0];$('#customFields').hidden=k!=='custom';$('#customVirus').required=k==='custom';$('#sequence').required=k==='custom';$('#targetNote').textContent=k==='custom'?'Supply a verified target sequence':'Example target · sequence required for real inference'};
$('#screenForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const k=$('#virus').value;if(k==='custom'&&!/^[ACDEFGHIKLMNPQRSTVWY\s]+$/i.test($('#sequence').value.trim())){toast('Use standard amino-acid letters for the target sequence.');return}busy=true;const btn=$('.run');btn.disabled=true;$('#progress').hidden=false;const messages=['Preparing example research context…','Applying illustrative compound scores…','Organising the research shortlist…'];for(const m of messages){$('#progress').textContent=m;await new Promise(r=>setTimeout(r,550))}const shift={sars:0,flu:3,hcv:6,custom:9}[k];const n=$('#library').value==='focused'?6:12;data=base.slice(0,n).map((c,i)=>({...c,score:base[(i+shift)%12].score,unc:base[(i+shift)%12].unc}));const strategy=$('#strategy').value;data.sort(strategy==='uncertain'?(a,b)=>b.unc-a.unc:strategy==='score'?(a,b)=>b.score-a.score:(a,b)=>(b.score-b.unc*.2)-(a.score-a.unc*.2));activeContext=k==='custom'?$('#customVirus').value.trim()+' · custom protein':targets[k][1];$('#agentTarget').textContent=activeContext;$('#runs').textContent=++runCount;$('#progress').hidden=true;btn.disabled=false;busy=false;$('#search').value='';$('#filter').value='all';setView('overview');render();addMessage('assistant',`Demo screening complete for ${activeContext}. ${data.length} fictional candidates are organised using your selected strategy. These are arbitrary demonstration scores; no compounds or protein sequences were evaluated by a model.`);toast('Demo screening complete. Explore your candidate shortlist.');};
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('fairouz-shortlist',JSON.stringify([...saved]))}catch{}render();return}const b=e.target.closest('[data-detail]');if(b)showDetail(b.dataset.detail)});
function showDetail(id){const c=data.find(x=>x.id===id);if(!c)return;$('#detailContent').innerHTML=`<div class="eyebrow">FICTIONAL RESEARCH CANDIDATE</div><h2 style="font-size:28px;margin:10px 0">${c.id}</h2><p>${c.scaffold} · Demo library</p><div class="detail-metrics"><div><strong>${c.score}</strong><small>Arbitrary demo score</small></div><div><strong>${c.unc}</strong><small>Illustrative uncertainty / 100</small></div></div><p><strong>Evidence status: no experimental or predicted evidence.</strong></p><p>This fictional identifier has no chemical structure, SMILES or known antiviral activity. It demonstrates how a real candidate record could display model output, provenance and assay results.</p><p>Next research step: verify target relevance and model applicability, then plan validation with qualified researchers. A predicted interaction cannot establish a treatment.</p><button class="button primary" id="detailSave">${saved.has(id)?'Remove from shortlist':'Save to shortlist'}</button>`;$('#detailSave').onclick=()=>{saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('fairouz-shortlist',JSON.stringify([...saved]))}catch{}render();$('#detail').close();toast('Shortlist updated')};$('#detail').showModal()}
$('.close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};
function addMessage(role,text){const d=document.createElement('div');d.className='message '+role;const s=document.createElement('small');s.textContent=role==='user'?'YOU':'FAIROUZ · SCRIPTED GUIDANCE';const p=document.createElement('p');p.textContent=text;d.append(s,p);$('#messages').append(d);$('#messages').scrollTop=$('#messages').scrollHeight}
function reply(q){const t=q.toLowerCase();if(/cure|treat|effective|patient|dose|prescri/.test(t))return 'This prototype cannot identify an effective treatment or recommend patient care. The compounds are fictional. Computational binding predictions would still need cellular activity, selectivity, toxicity and clinical validation before any treatment claim.';if(/learn|trial|error|feedback/.test(t))return 'Active learning needs real experimental feedback: select an informative batch, collect quality-controlled assay results, update a validated model, and rank the next batch. Repeatedly scoring the same compounds without new observations does not establish effectiveness. This demo does not retrain a model.';if(/rank|score|confidence|uncertain/.test(t))return 'The displayed scores are arbitrary, not probabilities of efficacy. Balanced exploration sorts by demo score minus 0.2 × demo uncertainty. Highest score sorts by score, and exploration sorts by uncertainty. A real model would need calibrated uncertainty, endpoint units and validation on held-out compounds and targets.';if(/next|test|assay/.test(t))return 'For a real study, first verify the viral target and candidate structures. Researchers would review relevant evidence, assay feasibility, selectivity and toxicity, then validate candidates under appropriate laboratory oversight. Save a demo candidate with the star to practise building a shortlist.';if(/deeppurpose|model|connect|backend/.test(t))return 'A real integration needs a Python inference service running a validated DeepPurpose checkpoint. It would receive compound SMILES and a protein sequence, and return model outputs with checkpoint version, endpoint, units and provenance. No such service is connected here.';return 'I can explain rankings, the active-learning loop, or research validation steps. This assistant uses scripted responses and cannot analyse a new virus. Select one in the screening form, or choose a custom target to explore the workflow.'}
function ask(q){if(!q.trim())return;addMessage('user',q.trim());addMessage('assistant',reply(q));$('#chatInput').value=''}$('#chatForm').onsubmit=e=>{e.preventDefault();ask($('#chatInput').value)};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>ask(b.dataset.prompt));
$('#export').onclick=()=>{const report={app:'Fairouz',exportedAt:new Date().toISOString(),context:activeContext,mode:'Illustrative demo. No AI model inference or clinical evidence.',strategy:$('#strategy').selectedOptions[0].text,screeningRuns:runCount,candidates:data.map(c=>({...c,fictional:true,shortlisted:saved.has(c.id)})),shortlistedIds:[...saved],limitations:['Compounds are fictional and have no chemical structures.','Scores and uncertainty values are arbitrary.','Binding predictions do not establish antiviral efficacy.','No clinical recommendations or laboratory results are provided.'],reference:'https://github.com/kexinhuang12345/DeepPurpose'};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='fairouz-research-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Research report exported')};render();
